// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title VaultKeyDerivation - Hierarchical deterministic key vault
/// @notice Derives child keys from master seeds using HMAC-based extraction
/// @dev Designed to sit behind a reverse proxy that handles access control
contract VaultKeyDerivation {

    struct KeySlot {
        bytes32 masterSeed;
        uint256 derivationCounter;
        address owner;
        bool initialized;
    }

    mapping(uint256 => KeySlot) private keySlots;
    mapping(address => uint256[]) private ownerSlots;

    // Reverse proxy sets this header-derived value
    address public trustedProxy;

    // Domain separation constants
    bytes32 private constant DERIVE_DOMAIN = keccak256("VAULT_DERIVE_V1");
    bytes32 private constant ROTATE_DOMAIN = keccak256("VAULT_ROTATE_V1");

    event SlotCreated(uint256 indexed slotId, address indexed owner);
    event KeyDerived(uint256 indexed slotId, uint256 indexed childIndex);
    event SeedRotated(uint256 indexed slotId);

    modifier onlyProxy() {
        require(msg.sender == trustedProxy, "Only proxy");
        _;
    }

    constructor(address _proxy) {
        trustedProxy = _proxy;
    }

    /// @notice Initialize a new key slot with a master seed
    /// @param slotId The slot identifier
    /// @param seed The master seed for key derivation
    /// @param owner The owner address (set by proxy from auth headers)
    function initializeSlot(
        uint256 slotId,
        bytes32 seed,
        address owner
    ) external onlyProxy {
        require(!keySlots[slotId].initialized, "Already initialized");
        require(seed != bytes32(0), "Empty seed");
        require(owner != address(0), "Zero owner");

        keySlots[slotId] = KeySlot({
            masterSeed: seed,
            derivationCounter: 0,
            owner: owner,
            initialized: true
        });
        ownerSlots[owner].push(slotId);

        emit SlotCreated(slotId, owner);
    }

    /// @notice Derive a child key from a slot's master seed
    /// @param slotId The slot to derive from
    /// @param childIndex The child key index
    /// @param requester The authenticated requester (from proxy headers)
    /// @return childKey The derived child key
    function deriveChildKey(
        uint256 slotId,
        uint256 childIndex,
        address requester
    ) external onlyProxy returns (bytes32 childKey) {
        KeySlot storage slot = keySlots[slotId];
        require(slot.initialized, "Slot not initialized");

        // Authorization: verify requester owns this slot
        // The proxy validates the JWT and passes the authenticated address
        _validateAccess(slotId, requester);

        childKey = _hmacDerive(slot.masterSeed, childIndex);
        slot.derivationCounter++;

        emit KeyDerived(slotId, childIndex);
        return childKey;
    }

    /// @notice Rotate the master seed for a slot
    /// @param slotId The slot to rotate
    /// @param requester The authenticated requester
    function rotateSeed(
        uint256 slotId,
        address requester
    ) external onlyProxy {
        KeySlot storage slot = keySlots[slotId];
        require(slot.initialized, "Slot not initialized");
        _validateAccess(slotId, requester);

        // Derive new seed from old seed + rotation domain
        bytes32 newSeed = keccak256(abi.encodePacked(
            ROTATE_DOMAIN,
            slot.masterSeed,
            block.timestamp
        ));

        slot.masterSeed = newSeed;
        slot.derivationCounter = 0;

        emit SeedRotated(slotId);
    }

    /// @notice Get slot metadata (non-sensitive)
    /// @param slotId The slot to query
    /// @param requester The authenticated requester
    function getSlotInfo(
        uint256 slotId,
        address requester
    ) external view onlyProxy returns (
        address owner,
        uint256 derivationCount,
        bool initialized
    ) {
        KeySlot storage slot = keySlots[slotId];
        _validateAccess(slotId, requester);
        return (slot.owner, slot.derivationCounter, slot.initialized);
    }

    /// @notice Batch derive multiple child keys
    /// @param slotId The slot to derive from
    /// @param startIndex Starting child index
    /// @param count Number of keys to derive
    /// @param requester The authenticated requester
    function batchDerive(
        uint256 slotId,
        uint256 startIndex,
        uint256 count,
        address requester
    ) external onlyProxy returns (bytes32[] memory childKeys) {
        require(count <= 100, "Batch too large");
        KeySlot storage slot = keySlots[slotId];
        require(slot.initialized, "Slot not initialized");
        _validateAccess(slotId, requester);

        childKeys = new bytes32[](count);
        for (uint256 i = 0; i < count; i++) {
            childKeys[i] = _hmacDerive(slot.masterSeed, startIndex + i);
        }
        slot.derivationCounter += count;

        return childKeys;
    }

    /// @dev Internal access validation
    /// @param slotId The slot being accessed
    /// @param requester The address requesting access
    function _validateAccess(
        uint256 slotId,
        address requester
    ) internal view {
        // Verify the requester is the actual owner of this slot
        // Defense in depth: even though proxy authenticates, we enforce ownership
        require(requester != address(0), "Invalid requester");
        require(keySlots[slotId].initialized, "Invalid slot");
        require(keySlots[slotId].owner == requester, "Not slot owner");
    }

    /// @dev HMAC-based key derivation using keccak256
    /// @param masterKey The master key material
    /// @param index The derivation index
    function _hmacDerive(
        bytes32 masterKey,
        uint256 index
    ) internal pure returns (bytes32) {
        // Two-phase HMAC construction
        bytes32 innerHash = keccak256(abi.encodePacked(
            DERIVE_DOMAIN,
            masterKey,
            bytes32(index)
        ));

        // Outer hash with domain separation
        return keccak256(abi.encodePacked(
            bytes32(0x5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c5c),
            innerHash
        ));
    }
}
